impl ::flatbuffers::Verifiable for ClientMessage<'_> {
  #[inline]
  fn run_verifier(
    v: &mut ::flatbuffers::Verifier, pos: usize
  ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
    v.visit_table(pos)?
     .visit_union::<ClientPayload, _>("payload_type", Self::VT_PAYLOAD_TYPE, "payload", Self::VT_PAYLOAD, false, |key, v, pos| {
        match key {
          ClientPayload::Connect => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<Connect>>("ClientPayload::Connect", pos),
          ClientPayload::PlayerInput => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<PlayerInput>>("ClientPayload::PlayerInput", pos),
          ClientPayload::BlockEditRequest => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<BlockEditRequest>>("ClientPayload::BlockEditRequest", pos),
          ClientPayload::BlockConfigUpdate => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<BlockConfigUpdate>>("ClientPayload::BlockConfigUpdate", pos),
          ClientPayload::SubBlockEditRequest => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<SubBlockEditRequest>>("ClientPayload::SubBlockEditRequest", pos),
          ClientPayload::ObserverConnect => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<ObserverConnect>>("ClientPayload::ObserverConnect", pos),
          ClientPayload::ClientSignalPublish => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<ClientSignalPublish>>("ClientPayload::ClientSignalPublish", pos),
          ClientPayload::LampConfigUpdate => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<LampConfigUpdate>>("ClientPayload::LampConfigUpdate", pos),
          ClientPayload::GrantCreate => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<GrantCreate>>("ClientPayload::GrantCreate", pos),
          ClientPayload::GrantRevoke => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<GrantRevoke>>("ClientPayload::GrantRevoke", pos),
          ClientPayload::AddHeldGrant => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<AddHeldGrant>>("ClientPayload::AddHeldGrant", pos),
          ClientPayload::ForgetHeldGrant => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<ForgetHeldGrant>>("ClientPayload::ForgetHeldGrant", pos),
          ClientPayload::RemoteSignalPublish => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<RemoteSignalPublish>>("ClientPayload::RemoteSignalPublish", pos),
          ClientPayload::TerminalChatSendData => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<TerminalChatSendData>>("ClientPayload::TerminalChatSendData", pos),
          ClientPayload::TabletInteractRequest => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<TabletInteractRequest>>("ClientPayload::TabletInteractRequest", pos),
          ClientPayload::TabletCursorUpdate => v.verify_union_variant::<::flatbuffers::ForwardsUOffset<TabletCursorUpdate>>("ClientPayload::TabletCursorUpdate", pos),
          _ => Ok(()),
        }
     })?
     .finish();
    Ok(())
  }
}
